<?php
defined('BASEPATH') or exit('No direct script access allowed');
final class NativeCompanyPostRefundController
{
    public static function handle($ci)
    {
        if(!CompanyRequestScope::sealedFor($ci)){show_error('Contexto indisponível.',503);return;}$ci->output->set_header('Cache-Control: no-store');require_once APPPATH.'services/CompanyPostRefundCancellation.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$csrf=$ci->session->userdata('native_post_refund_csrf');if(!is_string($csrf)||!preg_match('/^[a-f0-9]{64}$/D',$csrf)){$csrf=bin2hex(random_bytes(32));$ci->session->set_userdata('native_post_refund_csrf',$csrf);}$service=new CompanyPostRefundCancellation($ci->db,db_prefix());$detail=null;$error=null;
        try{if($ci->input->method(true)==='POST'){$token=$ci->input->post('native_post_refund_csrf',false);if(!is_string($token)||!hash_equals($csrf,$token)){show_error('Reabra a revisão antes de confirmar.',403);return;}$invoice=IssuerPolicy::id($ci->input->post('invoice_id',false));$action=$ci->input->post('action',false);if($action==='review'){$ci->load->library('encryption');$detail=$service->review($issuer,$actor,$invoice,fn($v)=>$ci->encryption->decrypt($v));}elseif($action==='cancel_local'){$service->cancel($issuer,$actor,$invoice,(string)$ci->input->post('refund_request',false),$ci->input->post('observation_id',false),(string)$ci->input->post('revision',false),(string)$ci->input->post('request_key',false),(string)$ci->input->post('reason',false),$ci->input->post('confirm_local',false)==='1');CompanyRequestScope::invalidateCaches($ci);redirect(CompanyRequestScope::adminUrl($ci,'payments/post_refund?source=company&invoice='.$invoice),'location',303);return;}elseif($action==='cancel_after_manual_reversal'){$proof=$ci->input->post('manual_reversal_proof',false);if(!is_array($proof))throw new DomainException('company_post_refund_manual_cycle_proof_required');$service->cancelAfterManualReversal($issuer,$actor,$invoice,(string)$ci->input->post('refund_request',false),$ci->input->post('observation_id',false),(string)$ci->input->post('revision',false),(string)$ci->input->post('request_key',false),(string)$ci->input->post('reason',false),$ci->input->post('confirm_local',false)==='1',$proof);CompanyRequestScope::invalidateCaches($ci);redirect(CompanyRequestScope::adminUrl($ci,'payments/post_refund?source=company&invoice='.$invoice),'location',303);return;}else throw new DomainException('company_post_refund_invalid');}elseif(in_array($ci->input->method(true),['GET','HEAD'],true))$detail=$service->page($issuer,$actor,$ci->input->get('invoice',false));else{show_error('Método não permitido.',405);return;}}
        catch(DomainException$e){$code=$e->getMessage();if(str_contains($code,'denied')||str_contains($code,'grant')||str_contains($code,'unverified')){show_error('Revisão indisponível nesta empresa ou autorização revogada.',403);return;}$ci->output->set_status_header(str_contains($code,'stale')||str_contains($code,'conflict')?409:422);$error='Cancelamento não confirmado. Consulte novamente e revise estado final, saldo, conta, autorização e motivo. Nenhuma baixa remota foi solicitada.';}
        catch(Throwable$e){$ci->output->set_status_header(503);log_message('error','Post-refund local cancellation unconfirmed; private proof omitted.');$error='Resultado local não confirmado. Reabra esta mesma fatura; preserve a chave da operação antes de retomar.';}
        $ci->load->view('admin/payments/company_post_refund',['detail'=>$detail,'error'=>$error,'native_post_refund_csrf'=>$csrf]);
    }
}
